window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-6db2d8234ad713ae"]={"versions": [{"id": "FIG-6db2d8234ad713ae", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung des internen Kontrollflusses der Prüffunktion <code>E2E_P01_process_NoNewOrRepeatedDataCounter</code> innerhalb der AUTOSAR E2E Library (E2E Profile 1, Classic/Adaptive Platform). Es beschreibt einen Teilschritt der E2E-Prüfroutine (<code>E2E_P01Check</code>), der den Zähler für ausbleibende oder wiederholte Daten aktualisiert.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Zustandsstruktur</strong>: <code>State</code> (Zeiger auf <code>E2E_P01CheckStateType</code>) mit dem Zustandsfeld <code>NoNewOrRepeatedDataCounter</code>.\n</li><li><strong>Entscheidungsknoten (Decision Node)</strong>: Bedingungsprüfung <code>State-&gt;NoNewOrRepeatedDataCounter &lt; 14</code>.\n</li><li><strong>Aktionsknoten (Action Node)</strong>: Inkrementierungsoperation <code>State-&gt;NoNewOrRepeatedDataCounter++</code>.\n</li><li><strong>Zusammenführungsknoten (Merge Node)</strong>: Zusammenführung der beiden Kontrollflusszweige vor Erreichen des Endknotens.\n</li><li><strong>Initial- und Aktivitätsendknoten</strong>: Start und reguläres Verlassen des Teilschritts.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Ablauf beginnt am Initialknoten und führt auf die Verzweigung zur Bedingungsprüfung.\n</li><li>Es wird geprüft, ob <code>State-&gt;NoNewOrRepeatedDataCounter &lt; 14</code> zutrifft:\n<ul class=\"fig-list\"><li><strong>[TRUE]</strong>: Der Zweig führt zur Aktion <code>State-&gt;NoNewOrRepeatedDataCounter++</code>, in welcher der Zähler um 1 erhöht wird. Anschließend wird der Kontrollfluss auf den Zusammenführungsknoten geführt.\n</li><li><strong>[FALSE]</strong>: Der Inkrementierungsschritt wird umgangen, und der Kontrollfluss führt direkt unter Beibehaltung des aktuellen Zählerwerts zum Zusammenführungsknoten.\n</li></ul>\n</li><li>Vom Zusammenführungsknoten führt die Sequenz unmittelbar zum Aktivitätsendknoten.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Logik ist normativ verbindlich für die Implementierung von <code>E2E_P01Check</code>. Sie definiert eine Sättigungsgrenze (Saturation) für <code>NoNewOrRepeatedDataCounter</code> bei maximal 14, um Zählerüberläufe zu verhindern. Software-Entwickler müssen sicherstellen, dass bei Erreichen des Grenzwerts 14 kein weiterer Überlauf stattfindet und der Wert unverändert bleibt.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-5cf031f7aebc8c3b", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung des internen Kontrollflusses der Prüffunktion <code>E2E_P01_process_NoNewOrRepeatedDataCounter</code> innerhalb der AUTOSAR E2E Library (E2E Profile 1, Classic/Adaptive Platform). Es beschreibt einen Teilschritt der E2E-Prüfroutine (<code>E2E_P01Check</code>), der den Zähler für ausbleibende oder wiederholte Daten aktualisiert.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Zustandsstruktur</strong>: <code>State</code> (Zeiger auf <code>E2E_P01CheckStateType</code>) mit dem Zustandsfeld <code>NoNewOrRepeatedDataCounter</code>.\n</li><li><strong>Entscheidungsknoten (Decision Node)</strong>: Bedingungsprüfung <code>State-&gt;NoNewOrRepeatedDataCounter &lt; 14</code>.\n</li><li><strong>Aktionsknoten (Action Node)</strong>: Inkrementierungsoperation <code>State-&gt;NoNewOrRepeatedDataCounter++</code>.\n</li><li><strong>Zusammenführungsknoten (Merge Node)</strong>: Zusammenführung der beiden Kontrollflusszweige vor Erreichen des Endknotens.\n</li><li><strong>Initial- und Aktivitätsendknoten</strong>: Start und reguläres Verlassen des Teilschritts.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Ablauf beginnt am Initialknoten und führt auf die Verzweigung zur Bedingungsprüfung.\n</li><li>Es wird geprüft, ob <code>State-&gt;NoNewOrRepeatedDataCounter &lt; 14</code> zutrifft:\n<ul class=\"fig-list\"><li><strong>[TRUE]</strong>: Der Zweig führt zur Aktion <code>State-&gt;NoNewOrRepeatedDataCounter++</code>, in welcher der Zähler um 1 erhöht wird. Anschließend wird der Kontrollfluss auf den Zusammenführungsknoten geführt.\n</li><li><strong>[FALSE]</strong>: Der Inkrementierungsschritt wird umgangen, und der Kontrollfluss führt direkt unter Beibehaltung des aktuellen Zählerwerts zum Zusammenführungsknoten.\n</li></ul>\n</li><li>Vom Zusammenführungsknoten führt die Sequenz unmittelbar zum Aktivitätsendknoten.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Logik ist normativ verbindlich für die Implementierung von <code>E2E_P01Check</code>. Sie definiert eine Sättigungsgrenze (Saturation) für <code>NoNewOrRepeatedDataCounter</code> bei maximal 14, um Zählerüberläufe zu verhindern. Software-Entwickler müssen sicherstellen, dass bei Erreichen des Grenzwerts 14 kein weiterer Überlauf stattfindet und der Wert unverändert bleibt.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-6db2d8234ad713ae", "to": "FIG-5cf031f7aebc8c3b", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
